    window.getAdminEmails = getAdminEmails;
    function saveAdminEmails(list) {
      if (!Array.isArray(list)) list = [];
      try {
        localStorage.setItem("mmo_admin_emails", JSON.stringify(list));
      } catch(e) {}
      if (typeof renderAdminEmailsList === "function") renderAdminEmailsList();
      if (typeof callGasApi === "function") {
        const callerEmail = (typeof currentUser !== "undefined" && currentUser && currentUser.email) ? currentUser.email : (list[0] || ROOT_ADMIN_EMAIL);
        callGasApi("adminSaveSettings", {
          adminEmail: callerEmail,
          settings: {
            adminEmails: list.join(",")
          }
        }).catch(err => console.warn("Lỗi đồng bộ admin emails:", err));
      }
    }
    window.saveAdminEmails = saveAdminEmails;
    async function syncAdminEmailsFromCloud() {
      try {
        if (typeof callGasApi !== "function") return;
        const currentList = getAdminEmails();
        const queryEmail = (typeof currentUser !== "undefined" && currentUser && currentUser.email) ? currentUser.email : (currentList[0] || ROOT_ADMIN_EMAIL);
        const res = await callGasApi("adminGetSettings", { adminEmail: queryEmail });
        if (res && res.success && res.settings) {
          const curSettings = getGeneralSettings();
          const isRecentlySavedLocally = curSettings._lastSavedAt && (Date.now() - curSettings._lastSavedAt < 300000);
          let hasSettingsChange = false;
          const cloudTicker = res.settings.tickerText || res.settings.TICKER_TEXT;
          if (cloudTicker !== undefined && cloudTicker !== null && cloudTicker.trim()) {
            if (!isRecentlySavedLocally && cloudTicker.trim() !== (curSettings.marqueeText || "").trim()) {
              curSettings.marqueeText = cloudTicker.trim();
              hasSettingsChange = true;
              if (typeof syncMarqueeNotice === "function") syncMarqueeNotice(curSettings.marqueeText);
            }
          }
          const cloudHotline = res.settings.hotline || res.settings.HOTLINE;
          if (cloudHotline !== undefined && cloudHotline !== null && cloudHotline.trim()) {
            if (!isRecentlySavedLocally && cloudHotline.trim() !== (curSettings.hotline || "").trim()) {
              curSettings.hotline = cloudHotline.trim();
              hasSettingsChange = true;
              if (typeof syncZaloLinks === "function") syncZaloLinks(curSettings.hotline);
              if (document.getElementById("setHotline")) document.getElementById("setHotline").value = curSettings.hotline;
            }
          }
          const cloudTelegram = res.settings.telegram || res.settings.TELEGRAM;
          if (cloudTelegram !== undefined && cloudTelegram !== null && cloudTelegram.trim()) {
            if (!isRecentlySavedLocally && cloudTelegram.trim() !== (curSettings.telegram || "").trim()) {
              curSettings.telegram = cloudTelegram.trim();
              hasSettingsChange = true;
              if (typeof syncTelegramLinks === "function") syncTelegramLinks(curSettings.telegram);
              if (document.getElementById("setTelegram")) document.getElementById("setTelegram").value = curSettings.telegram;
            }
          }
          const cloudSiteName = res.settings.siteName || res.settings.SITE_NAME;
          if (cloudSiteName !== undefined && cloudSiteName !== null && cloudSiteName.trim()) {
            if (!isRecentlySavedLocally && cloudSiteName.trim() !== (curSettings.siteName || "").trim()) {
              curSettings.siteName = cloudSiteName.trim();
              hasSettingsChange = true;
              if (typeof applyBrandCustomizations === "function") applyBrandCustomizations(curSettings);
              if (document.getElementById("setSiteName")) document.getElementById("setSiteName").value = curSettings.siteName;
            }
          }
          if (hasSettingsChange) {
            localStorage.setItem("mmo_system_settings", JSON.stringify(curSettings));
            localStorage.setItem("mmo_general_settings", JSON.stringify(curSettings));
          }
          if (res.settings.adminEmails) {
            let cloudEmails = res.settings.adminEmails.split(",").map(e => (e || "").trim().toLowerCase()).filter(Boolean);
            if (cloudEmails.length > 0) {
              const rootEmail = (ROOT_ADMIN_EMAIL || "").toLowerCase().trim();
              if (rootEmail && !cloudEmails.includes(rootEmail)) {
                cloudEmails.unshift(rootEmail);
              }
              localStorage.setItem("mmo_admin_emails", JSON.stringify(cloudEmails));
              if (typeof renderAdminEmailsList === "function") renderAdminEmailsList();
              if (typeof currentUser !== "undefined" && currentUser && currentUser.email) {
                const myEmail = currentUser.email.toLowerCase().trim();
                if (!cloudEmails.includes(myEmail)) {
                  currentUser.role = "Thành Viên";
                  localStorage.setItem("mmo_user", JSON.stringify(currentUser));
                  if (typeof updateUserUI === "function") updateUserUI();
                  const curView = localStorage.getItem("mmo_current_view");
                  if (curView === "viewAdmin" && typeof switchView === "function") {
                    showToast("⚠️ Tài khoản của bạn đã bị rút quyền Quản Trị Viên!", "warning");
                    switchView("viewStore");
                  }
                }
              }
            }
          }
        }
      } catch(e) {
        console.warn("syncAdminEmailsFromCloud error:", e);
      }
    }
    window.syncAdminEmailsFromCloud = syncAdminEmailsFromCloud;
    function isAdminUser(user) {
      if (!user) {
        if (typeof currentUser !== "undefined" && currentUser) {
          user = currentUser;
        } else {
          try {
            const stored = localStorage.getItem("mmo_user");
            if (stored) user = JSON.parse(stored);
          } catch(e) {}
        }
      }
      if (!user || !user.email) return false;
      const userEmail = (user.email || "").toLowerCase().trim();
      const adminList = (typeof getAdminEmails === "function") ? getAdminEmails().map(e => (e || "").toLowerCase().trim()) : [];
      if (adminList.includes(userEmail)) return true;
      if (user.role === "Quản Trị Viên" || user.role === "ADMIN" || user.role === "Admin") {
        user.role = "Thành Viên";
        if (typeof currentUser !== "undefined" && currentUser && (currentUser.email || "").toLowerCase().trim() === userEmail) {
          currentUser.role = "Thành Viên";
          try { localStorage.setItem("mmo_user", JSON.stringify(currentUser)); } catch(e) {}
          if (typeof updateUserUI === "function") updateUserUI();
        }
      }
      return false;
    }
    window.isAdminUser = isAdminUser;
    function handleAddAdminEmail() {
      const input = document.getElementById("newAdminEmailInput");
      const email = (input?.value || "").trim().toLowerCase();
      if (!email || !email.includes("@")) {
        showToast("Vui lòng nhập địa chỉ email hợp lệ!", "warning");
        return;
      }
      const list = getAdminEmails();
      if (list.map(e => (e || "").toLowerCase().trim()).includes(email)) {
        showToast("Email này đã có trong danh sách quản trị!", "warning");
        return;
      }
      list.push(email);
      saveAdminEmails(list);
      let users = getRegisteredUsers();
      const uIdx = users.findIndex(u => (u.email || "").toLowerCase().trim() === email);
      if (uIdx !== -1) {
        users[uIdx].role = "Quản Trị Viên";
      } else {
        const newUserObj = {
          name: email.split("@")[0],
          email: email,
          role: "Quản Trị Viên",
          balance: 0,
          created: new Date().toLocaleDateString("vi-VN"),
          avatar: "https://api.dicebear.com/7.x/bottts/svg?seed=" + encodeURIComponent(email)
        };
        users.unshift(newUserObj);
      }
      saveRegisteredUsers(users);
      if (currentUser && (currentUser.email || "").toLowerCase().trim() === email) {
        currentUser.role = "Quản Trị Viên";
        try {
          localStorage.setItem("mmo_user", JSON.stringify(currentUser));
        } catch(e) {}
        updateUserUI();
      }
      if (input) input.value = "";
      if (typeof renderAdminEmailsList === "function") renderAdminEmailsList();
      if (typeof renderAdminUsersTable === "function") renderAdminUsersTable();
      if (typeof renderAdminDashboard === "function") renderAdminDashboard();
      showToast("🎉 Đã cấp quyền Quản Trị Viên thành công cho: " + email, "success");
    }
    window.handleAddAdminEmail = handleAddAdminEmail;
    function handleRemoveAdminEmail(email) {
      const targetEmail = (email || "").toLowerCase().trim();
      if (targetEmail === (ROOT_ADMIN_EMAIL || "").toLowerCase().trim()) {
        showToast("⛔ Không thể xóa tài khoản Quản Trị Viên gốc!", "error");
        return;
      }
      let list = getAdminEmails();
      if (list.length <= 1) {
        showToast("⚠️ Hệ thống phải duy trì ít nhất 1 Quản Trị Viên!", "warning");
        return;
      }
      if (!confirm("⚠️ Bạn có chắc muốn XÓA quyền Quản Trị Viên của [" + email + "]?")) return;
      list = list.filter(e => (e || "").toLowerCase().trim() !== targetEmail);
      saveAdminEmails(list);
      let users = getRegisteredUsers();
      const uIdx = users.findIndex(u => (u.email || "").toLowerCase().trim() === targetEmail);
      if (uIdx !== -1) {
        users[uIdx].role = "Thành Viên";
        saveRegisteredUsers(users);
      }
      if (currentUser && (currentUser.email || "").toLowerCase().trim() === targetEmail) {
        currentUser.role = "Thành Viên";
        try {
          localStorage.setItem("mmo_user", JSON.stringify(currentUser));
        } catch(e) {}
        updateUserUI();
        showToast("Tài khoản của bạn đã bị gỡ quyền Quản Trị Viên!", "warning");
        if (typeof switchView === "function") switchView("viewStore");
      }
      if (typeof renderAdminEmailsList === "function") renderAdminEmailsList();
      if (typeof renderAdminUsersTable === "function") renderAdminUsersTable();
      if (typeof renderAdminDashboard === "function") renderAdminDashboard();
      showToast("🗑️ Đã xóa quyền Quản Trị Viên của: " + email, "success");
    }
