      const prodId = (p && p.id) || new URLSearchParams(window.location.search).get('prod') || "";
      let shareUrl = prodId ? ("https://mmo-shop-api.manhdongvtc.workers.dev/og?prod=" + encodeURIComponent(prodId)) : (window.location.origin + window.location.pathname);
