    async function syncLocalStockToTurso() {
      if (!TURSO_CLIENT.isConfigured()) {
        showToast("Vui lòng cấu hình URL Worker API trước!", "warning");
        return;
      }
      const logBox = document.getElementById("tursoLogBox");
      if (logBox) {
        logBox.style.display = "block";
        logBox.innerText = "⏳ Đang quét và tải toàn bộ kho tài khoản lên Turso Database qua Worker API...";
      }
      try {
        let totalUploaded = 0;
        if (typeof MOCK_DATA !== "undefined" && Array.isArray(MOCK_DATA.products)) {
          for (const prod of MOCK_DATA.products) {
            const hasVars = Array.isArray(prod.variants) && prod.variants.length > 0;
            if (hasVars) {
              for (let vi = 0; vi < prod.variants.length; vi++) {
                const v = prod.variants[vi];
                if (Array.isArray(v.accounts) && v.accounts.length > 0) {
                  await MMO_WORKER_API.adminImportAccounts(prod.id, vi, v.accounts);
                  totalUploaded += v.accounts.length;
                }
              }
            } else if (Array.isArray(prod.accounts) && prod.accounts.length > 0) {
              await MMO_WORKER_API.adminImportAccounts(prod.id, 0, prod.accounts);
              totalUploaded += prod.accounts.length;
            }
          }
        }
        if (logBox) {
          logBox.innerText = "✅ ĐÃ ĐỒNG BỘ LÊN TURSO THÀNH CÔNG!\n- Đã nạp an toàn: " + totalUploaded + " tài khoản lên Turso Database.";
          logBox.style.color = "#34d399";
        }
        showToast("🎉 Đã tải " + totalUploaded + " tài khoản lên Turso API!", "success");
        if (typeof syncTursoStockToLocalUI === "function") syncTursoStockToLocalUI();
      } catch(err) {
        if (logBox) {
          logBox.innerText = "❌ Lỗi khi tải lên Turso API:\n" + err.message;
          logBox.style.color = "#ef4444";
        }
        showToast("Lỗi đồng bộ: " + err.message, "danger");
      }
    }
