    async function executeQuickTestBuy() {
      const sel = document.getElementById("quickTestProdSelect");
      const btn = document.getElementById("btnQuickTestBuy");
      const resBox = document.getElementById("quickTestResultBox");
      if (!sel) return;
      const prodId = sel.value;
      const opt = sel.selectedOptions[0];
      const prodName = opt ? opt.innerText : "Sản phẩm " + prodId;
      const price = opt ? Number(opt.getAttribute("data-price") || 0) : 0;
      const provider = opt ? (opt.getAttribute("data-provider") || "mail72h") : "mail72h";
      const pCfg = (typeof API_SOURCES !== "undefined" && API_SOURCES[provider]) ? API_SOURCES[provider] : API_SOURCES.mail72h;
      if (!confirm("Xác nhận mua test 1 tài khoản [" + prodName + "] từ " + pCfg.name + "? (Trừ " + formatVND(price) + " từ ví nguồn)")) return;
      const originalBtnHtml = btn ? btn.innerHTML : "";
      if (btn) {
        btn.innerHTML = "<i class='fa-solid fa-spinner fa-spin'></i> Đang mua test...";
        btn.disabled = true;
      }
      if (resBox) resBox.style.display = "none";
      try {
        const res = await executeSourceApiCall("buyProduct", { productId: prodId, amount: 1, provider: provider, baseUrl: pCfg.baseUrl, apiKey: pCfg.apiKey });
        if (res && res.success && Array.isArray(res.accounts) && res.accounts.length > 0) {
          if (resBox) {
            resBox.style.display = "block";
            resBox.innerHTML = '<span style="color:#10b981; font-weight:700;"><i class="fa-solid fa-circle-check"></i> Test thành công từ ' + pCfg.name + '!</span><br/>' +
              '<span style="color:#38bdf8;">Đơn nguồn: ' + (res.trans_id || '') + '</span><br/>' +
              '<code>' + escapeHtml(res.accounts[0]) + '</code>';
          }
          if (typeof showToast === "function") showToast("Mua test thành công 1 tài khoản từ " + pCfg.name + "!", "success");
          fetchSingleSourceProfile(provider, false);
        } else {
          throw new Error((res && res.message) ? res.message : "Giao dịch test không thành công");
        }
      } catch(err) {
        if (typeof showToast === "function") showToast("Lỗi mua test: " + err.message, "danger");
      } finally {
        if (btn) {
          btn.innerHTML = originalBtnHtml;
          btn.disabled = false;
        }
      }
    }
