      const btnEx = document.getElementById("subBtnProfExchangedOrders");
      const btnDone = document.getElementById("subBtnProfCompletedOrders");
      if (btnAll) {
        btnAll.style.background = (tabKey === "ALL") ? "#1e293b" : "#0f172a";
        btnAll.style.color = (tabKey === "ALL") ? "#38bdf8" : "#94a3b8";
        btnAll.style.borderColor = (tabKey === "ALL") ? "rgba(56,189,248,0.4)" : "#1e293b";
      }
