      if (gbMatch && gbMatch[1]) giaBan = gbMatch[1].trim();
      const gcMatch = html.match(/\[giacu\](.*?)\[\/giacu\]/i);
      if (gcMatch && gcMatch[1]) giaCu = gcMatch[1].trim();
      html = html.replace(/\[giaban\].*?\[\/giaban\]/gi, "");
      html = html.replace(/\[giacu\].*?\[\/giacu\]/gi, "");
      html = html.replace(/\[tomtat\]/gi, "").replace(/\[\/tomtat\]/gi, "");
      let priceBadgeHtml = "";
      if (giaBan) {
        priceBadgeHtml = '<div style="background:#0b111e; border:1px solid #10b981; border-radius:8px; padding:12px 18px; margin:16px 0; display:inline-flex; align-items:center; gap:12px;">' +
          '<span style="color:#94a3b8; font-size:0.85rem;">Giá niêm yết:</span>' +
          '<span style="color:#10b981; font-weight:800; font-size:1.2rem;">' + escapeHtml(giaBan) + '</span>' +
          (giaCu ? '<span style="color:#64748b; text-decoration:line-through; font-size:0.9rem;">' + escapeHtml(giaCu) + '</span>' : '') +
        '</div>';
      }
      html = html.replace(/background(-color)?\s*:\s*(#ffffff|#fff|white|rgb\(255,\s*255,\s*255\)|rgba\(255,\s*255,\s*255,\s*1\))/gi, "background: transparent");
      html = html.replace(/color\s*:\s*(#000000|#000|#202124|#222222|#222|black|rgb\(0,\s*0,\s*0\)|rgb\(32,\s*33,\s*36\))/gi, "color: inherit");
      return priceBadgeHtml + html;
