    window.renderArticleSidebarTop = renderArticleSidebarTop;
    function getRelatedProductsForBlog(blog, limit) {
      if (!limit) limit = 3;
      var prods = (MOCK_DATA && MOCK_DATA.products) ? MOCK_DATA.products.filter(function(p) { return !p.isDeleted; }) : [];
      if (!prods.length) return [];
      if (!blog) return prods.slice(0, limit);
      var titleRaw = (blog.title || '').toLowerCase();
      var textRaw = [
        blog.title || '',
        blog.category || '',
        blog.snippet || '',
        blog.tags || ''
      ].join(' ').toLowerCase();
      var TOPIC_RULES = [
        { topic: 'gmail', regex: /(gmail|google|mail|email|hop thu|gg drive|google drive|workspace)/i, prodKeywords: ['gmail', 'google', 'mail', 'email'] },
        { topic: 'facebook', regex: /(facebook|fb|via|clone|fanpage|bm|business manager|page|ads fb)/i, prodKeywords: ['facebook', 'fb', 'via', 'clone', 'fanpage', 'bm'] },
        { topic: 'tiktok', regex: /(tiktok|tik tok|douyin|affiliate tiktok|shop tiktok|live tiktok|us|brazil|beta)/i, prodKeywords: ['tiktok', 'tik tok', 'douyin', 'beta'] },
        { topic: 'kling', regex: /(kling|kling ai)/i, prodKeywords: ['kling'] },
        { topic: 'chatgpt', regex: /(chatgpt|gpt|chat gpt|openai)/i, prodKeywords: ['chatgpt', 'chat gpt', 'gpt', 'openai'] },
        { topic: 'gemini', regex: /(gemini|google ai)/i, prodKeywords: ['gemini'] },
        { topic: 'canva', regex: /(canva)/i, prodKeywords: ['canva'] },
        { topic: 'capcut', regex: /(capcut|cap cut)/i, prodKeywords: ['capcut'] },
        { topic: 'ai', regex: /(ai|video ai|tri tue nhan tao)/i, prodKeywords: ['ai', 'kling', 'chatgpt', 'canva', 'capcut', 'gemini'] },
        { topic: 'hotmail', regex: /(hotmail|outlook|microsoft|live mail)/i, prodKeywords: ['hotmail', 'outlook', 'microsoft'] },
        { topic: 'proxy', regex: /(proxy|vpn|ipv4|ipv6|socks5|fake ip|doi ip|hma)/i, prodKeywords: ['proxy', 'vpn', 'socks', 'hma'] },
        { topic: 'rom', regex: /(rom|adb|phone farm|box phone|samsung|j7|s10|note)/i, prodKeywords: ['rom', 'adb', 'farm', 'j7', 's10', 'samsung'] },
        { topic: 'instagram', regex: /(instagram|insta|ig)/i, prodKeywords: ['instagram', 'insta', 'ig'] },
        { topic: 'youtube', regex: /(youtube|yt|premium)/i, prodKeywords: ['youtube', 'yt', 'premium'] }
      ];
      var stopwords = ['cho', 'cac', 'nhung', 'cua', 'voi', 'trong', 'duoc', 'nay', 'cach', 'huong', 'dan', 'kiem', 'tien', 'mmo', 'lam', 'sao', 'de', 'va', 'hoac', 'la', 'khi', 'nao', 'bai', 'viet', 'chuan', 'moi', 'nhat', 'nam', '2026', '2025', '2024', 'hang', 'loat', 'tu', 'so', 'bao', 'mat'];
      var titleWords = titleRaw.replace(/[^a-z0-9\sà-ỹ]/gi, ' ').split(/\s+/).filter(function(w) {
        return w.length >= 3 && stopwords.indexOf(w) === -1;
      });
      var scored = prods.map(function(p) {
        var score = 0;
        var pName = (p.name || p.title || '').toLowerCase();
        var pCat = (p.category || '').toLowerCase();
        var pDesc = (p.description || '').toLowerCase();
        var pFull = pName + ' ' + pCat + ' ' + pDesc;
        titleWords.forEach(function(w) {
          if (pName.indexOf(w) !== -1) score += 200;
          else if (pCat.indexOf(w) !== -1) score += 100;
          else if (pFull.indexOf(w) !== -1) score += 40;
        });
        TOPIC_RULES.forEach(function(rule) {
          if (rule.regex.test(titleRaw)) {
            var matchedKw = rule.prodKeywords.filter(function(kw) { return pName.indexOf(kw) !== -1 || pCat.indexOf(kw) !== -1; });
            if (matchedKw.length > 0) {
              score += 300 + matchedKw.length * 50;
            }
          } else if (rule.regex.test(textRaw)) {
            var matchedKw2 = rule.prodKeywords.filter(function(kw) { return pName.indexOf(kw) !== -1 || pCat.indexOf(kw) !== -1; });
            if (matchedKw2.length > 0) {
              score += 60 + matchedKw2.length * 20;
            }
          }
        });
        var sold = p.buffSold || p.sold || 0;
        score += Math.min(25, Math.floor(sold / 5));
        return { product: p, score: score, sold: sold };
      });
      scored.sort(function(a, b) { return b.score - a.score; });
      var matched = scored.filter(function(s) { return s.score >= 100; }).map(function(s) { return s.product; });
      if (matched.length < limit) {
        var remaining = prods.filter(function(p) {
          return !matched.some(function(m) { return m.id === p.id; });
        });
        remaining.sort(function(a, b) {
          return (b.buffSold || b.sold || 0) - (a.buffSold || a.sold || 0);
        });
        remaining.forEach(function(p) {
          if (matched.length < limit) {
            matched.push(p);
          }
        });
      }
      return matched.slice(0, limit);
    }
    window.getRelatedProductsForBlog = getRelatedProductsForBlog;
