    function handleAddNewBlog() {
      const title = document.getElementById("admBlogTitle")?.value.trim();
      const cat = document.getElementById("admBlogCat")?.value;
      const img = document.getElementById("admBlogImg")?.value.trim();
      const snippet = document.getElementById("admBlogSnippet")?.value.trim();
      const content = document.getElementById("admBlogContent")?.value.trim();
      if (!title) {
        alert("Vui lòng nhập tiêu đề bài viết!");
        return;
      }
      if (!snippet) {
        alert("Vui lòng nhập đoạn tóm tắt (sa-pô) bài viết!");
        return;
      }
      const newId = "BLOG_" + String(Date.now()).slice(-6);
      const newBlog = {
        id: newId,
        title: title,
        category: cat || "Kiếm Tiền MMO",
        date: "Vừa xong",
        views: "1",
        image: img || "https://cdn.jsdelivr.net/gh/digimarketmmo/muabantaikhoanmmo-cdn@main/assets/images/blog_gmail.png",
        snippet: snippet,
        content: content || snippet
      };
      if (!MOCK_DATA.blogs) MOCK_DATA.blogs = [];
      MOCK_DATA.blogs.unshift(newBlog);
      try {
        localStorage.setItem("mmo_admin_blogs", JSON.stringify(MOCK_DATA.blogs));
      } catch(e) {}
      document.getElementById("admBlogTitle").value = "";
      document.getElementById("admBlogImg").value = "";
      document.getElementById("admBlogSnippet").value = "";
      document.getElementById("admBlogContent").value = "";
      alert("Đăng bài viết mới thành công!");
      renderAdminBlogsTable();
      if (typeof renderBlogPage === "function") renderBlogPage();
      if (typeof renderSidebarBlogs === "function") renderSidebarBlogs();
    }
