    function renderAllProductsPage() {
      const catContainer = document.getElementById("allProdCategoryList");
      if (catContainer) {
        const allProds = (typeof getVisibleProducts === "function") ? getVisibleProducts() : ((MOCK_DATA && MOCK_DATA.products) ? MOCK_DATA.products : []);
        const cats = (MOCK_DATA && MOCK_DATA.categories) ? MOCK_DATA.categories : ["Tất cả"];
        let catHtml = '';
        cats.forEach(function(cat) {
          const isAll = (cat === "Tất cả");
          const count = isAll ? allProds.length : allProds.filter(function(p) { return (p.category || "").toLowerCase() === cat.toLowerCase(); }).length;
          const isActive = (allProdCurrentCat === cat);
          const activeStyle = isActive 
            ? 'background:rgba(239,68,68,0.15); color:#ef4444; border:1px solid rgba(239,68,68,0.3); font-weight:700;' 
            : 'background:transparent; color:#cbd5e1; border:1px solid transparent;';
          const badgeStyle = isActive 
            ? 'background:#ef4444; color:#fff;' 
            : 'background:#1e293b; color:#94a3b8;';
          catHtml += '<div onclick="setAllProdCategory(&quot;' + escapeHtml(cat) + '&quot;)" style="display:flex; justify-content:space-between; align-items:center; padding:7px 12px; border-radius:6px; font-size:0.83rem; cursor:pointer; transition:all 0.2s; ' + activeStyle + '">' +
            '<span>' + escapeHtml(cat) + '</span>' +
            '<span style="font-size:0.72rem; padding:2px 7px; border-radius:4px; font-weight:700; ' + badgeStyle + '">' + count + '</span>' +
          '</div>';
        });
        catContainer.innerHTML = catHtml;
      }
      const container = document.getElementById("allProductsGrid");
      if (!container) return;
      let list = (typeof getVisibleProducts === "function") ? getVisibleProducts() : ((MOCK_DATA && MOCK_DATA.products) ? [...MOCK_DATA.products] : []);
      const q = (document.getElementById("allProdSearchInp")?.value || "").toLowerCase().trim();
      if (q) {
        list = list.filter(function(p) { return (p.name || "").toLowerCase().includes(q) || (p.category || "").toLowerCase().includes(q); });
      }
      if (allProdCurrentCat && allProdCurrentCat !== "Tất cả") {
        list = list.filter(function(p) { return (p.category || "").toLowerCase().includes(allProdCurrentCat.toLowerCase()); });
      }
      const minP = parseFloat(document.getElementById("allProdPriceMin")?.value) || 0;
      const maxP = parseFloat(document.getElementById("allProdPriceMax")?.value) || 0;
      if (minP > 0) {
        list = list.filter(function(p) { return (Number(p.price) || 0) >= minP; });
      }
      if (maxP > 0) {
        list = list.filter(function(p) { return (Number(p.price) || 0) <= maxP; });
      }
      const inStockOnly = document.getElementById("allProdInStockOnly")?.checked;
      if (inStockOnly) {
        list = list.filter(function(p) { return (p.stock === undefined || Number(p.stock) > 0); });
      }
      const countBadge = document.getElementById("allProdCountBadge");
      if (countBadge) countBadge.innerText = list.length + " kết quả";
      if (allProdCurrentSort === "bestseller") {
        list.sort(function(a, b) { return (b.sold || 0) - (a.sold || 0); });
      } else if (allProdCurrentSort === "price_asc") {
        list.sort(function(a, b) { return (a.price || 0) - (b.price || 0); });
      } else if (allProdCurrentSort === "price_desc") {
        list.sort(function(a, b) { return (b.price || 0) - (a.price || 0); });
      } else if (allProdCurrentSort === "newest") {
        list.reverse();
      }
      if (list.length === 0) {
        container.innerHTML = '<div style="grid-column: 1/-1; text-align:center; padding:60px 20px; color:#64748b;">' +
          '<i class="fa-solid fa-box-open" style="font-size:3rem; margin-bottom:12px; display:block; color:#334155;"></i>' +
          '<p style="font-size:1rem; color:#94a3b8;">Không tìm thấy sản phẩm nào phù hợp với bộ lọc.</p>' +
          '<button type="button" onclick="resetAllProdFilter()" style="margin-top:10px; background:#131d2e; border:1px solid #1e293b; color:#38bdf8; padding:8px 16px; border-radius:6px; cursor:pointer;">Đặt lại bộ lọc</button>' +
        '</div>';
        const pag = document.getElementById("allProductsPagination");
        if (pag) pag.innerHTML = "";
        return;
      }
      const totalPages = Math.ceil(list.length / ALL_PROD_PAGE_SIZE);
      if (allProdCurrentPage > totalPages) allProdCurrentPage = totalPages;
      if (allProdCurrentPage < 1) allProdCurrentPage = 1;
      const startIndex = (allProdCurrentPage - 1) * ALL_PROD_PAGE_SIZE;
      const pageProds = list.slice(startIndex, startIndex + ALL_PROD_PAGE_SIZE);
      if (allProdViewMode === "list") {
        container.className = "all-prods-list";
        container.style.display = "flex";
        container.style.flexDirection = "column";
        container.style.gap = "10px";
        container.innerHTML = pageProds.map(function(p) { return renderSingleCardListMode(p); }).join("");
      } else {
        container.className = "all-prods-grid";
        container.style.display = "";
        container.style.flexDirection = "";
        container.style.gridTemplateColumns = "";
        container.style.gap = "";
        container.innerHTML = pageProds.map(function(p) { return renderSingleCard(p, false); }).join("");
      }
      if (typeof renderPaginationUI === "function") {
        renderPaginationUI("allProductsPagination", allProdCurrentPage, list.length, "changeAllProdPage", ALL_PROD_PAGE_SIZE);
      }
    }
    window.renderAllProductsPage = renderAllProductsPage;
