        const isCancelled = rawStatus === 'CANCELLED' || rawStatus === 'REFUNDED' || rawStatusTxt.includes('hủy') || rawStatusTxt.includes('hoàn tiền') || Boolean(o.isCancelled) || Boolean(o.isRefunded);
