    function autoEnrichOrderCustomerAndTime(order, cleanId) {
      if (!order) return order;
      cleanId = String(cleanId || order.orderId || order.id || "").replace("#", "").trim();
      const now = new Date();
      const defaultDateStr = now.toLocaleDateString("vi-VN") + " " + now.toLocaleTimeString("vi-VN", { hour: "2-digit", minute: "2-digit" });
      if (!order.date || order.date === "--" || String(order.date).trim() === "") {
        if (order.createdAt && order.createdAt !== "--" && String(order.createdAt).trim() !== "") {
          order.date = order.createdAt;
        } else {
          try {
            const uOrders = typeof getUserOrders === "function" ? getUserOrders() : [];
            const uo = uOrders.find(o => (o.orderId === cleanId || o.id === cleanId));
            if (uo && (uo.date || uo.createdAt) && uo.date !== "--" && uo.createdAt !== "--") {
              order.date = uo.date || uo.createdAt;
            }
          } catch(e) {}
        }
      }
      if (!order.date || order.date === "--" || String(order.date).trim() === "") {
        try {
          const msgs = typeof getAllChatMessages === "function" ? getAllChatMessages() : [];
          for (let i = msgs.length - 1; i >= 0; i--) {
            const m = msgs[i];
            if (!m) continue;
            if ((m.orderData && (m.orderData.orderId === cleanId || m.orderData.id === cleanId)) || (m.text && m.text.includes(cleanId))) {
              if (m.time || m.date || m.timestamp) {
                order.date = m.time || m.date || (m.timestamp ? new Date(m.timestamp).toLocaleDateString("vi-VN") + " " + new Date(m.timestamp).toLocaleTimeString("vi-VN", { hour: "2-digit", minute: "2-digit" }) : "");
                break;
              }
            }
          }
        } catch(e) {}
      }
      if (!order.date || order.date === "--" || String(order.date).trim() === "") {
        try {
          const txs = typeof getTransactionHistory === "function" ? getTransactionHistory() : JSON.parse(localStorage.getItem("mmo_transactions") || "[]");
          if (Array.isArray(txs)) {
            const matchTx = txs.find(t => String(t.description || "").includes(cleanId) || String(t.memo || "").includes(cleanId));
            if (matchTx && (matchTx.date || matchTx.time)) {
              order.date = matchTx.date + (matchTx.time ? (" " + matchTx.time) : "");
            }
          }
        } catch(e) {}
      }
      if (!order.date || order.date === "--" || String(order.date).trim() === "") {
        order.date = defaultDateStr;
      }
      if (!order.createdAt || order.createdAt === "--" || String(order.createdAt).trim() === "") {
        order.createdAt = order.date;
      }
      let foundEmail = (order.email || order.userEmail || "").trim();
      let foundName = (order.userName || order.name || "").trim();
      const isInvalidEmail = (em) => {
        if (!em || em === "--" || typeof em !== "string") return true;
        const e = em.toLowerCase().trim();
        return !e.includes("@") || e.includes("khachhang@gmail.com") || e.includes("sample") || e.includes("test@gmail.com");
      };
      if (isInvalidEmail(foundEmail)) {
        try {
          const uOrders = typeof getUserOrders === "function" ? getUserOrders() : [];
          const uo = uOrders.find(o => (o.orderId === cleanId || o.id === cleanId));
          if (uo && !isInvalidEmail(uo.email || uo.userEmail)) {
            foundEmail = (uo.email || uo.userEmail).trim();
            if (uo.userName || uo.name) foundName = uo.userName || uo.name;
          }
        } catch(e) {}
      }
      if (isInvalidEmail(foundEmail)) {
        try {
          const msgs = typeof getAllChatMessages === "function" ? getAllChatMessages() : [];
          for (let i = msgs.length - 1; i >= 0; i--) {
            const m = msgs[i];
            if (!m) continue;
            if ((m.orderData && (m.orderData.orderId === cleanId || m.orderData.id === cleanId)) || (m.text && m.text.includes(cleanId))) {
              const em = (m.orderData && (m.orderData.email || m.orderData.userEmail)) || m.senderEmail || m.userEmail || m.email || (m.sender && m.sender.includes("@") ? m.sender : "");
              if (!isInvalidEmail(em) && !em.toLowerCase().includes("admin") && em.toLowerCase() !== "manhdongvtc@gmail.com" && em.toLowerCase() !== "manhdongdz@gmail.com") {
                foundEmail = em.trim();
                if (m.sender && !m.sender.includes("@")) foundName = m.sender;
                break;
              }
            }
          }
        } catch(e) {}
      }
      if (isInvalidEmail(foundEmail)) {
        if (typeof currentAdminChatTargetEmail !== "undefined" && currentAdminChatTargetEmail && !isInvalidEmail(currentAdminChatTargetEmail)) {
          foundEmail = currentAdminChatTargetEmail.trim();
        }
      }
      if (isInvalidEmail(foundEmail)) {
        try {
          const txs = typeof getTransactionHistory === "function" ? getTransactionHistory() : JSON.parse(localStorage.getItem("mmo_transactions") || "[]");
          if (Array.isArray(txs)) {
            const matchTx = txs.find(t => String(t.description || "").includes(cleanId) || String(t.memo || "").includes(cleanId));
            if (matchTx && !isInvalidEmail(matchTx.userEmail || matchTx.email)) {
              foundEmail = (matchTx.userEmail || matchTx.email).trim();
              if (matchTx.userName || matchTx.name) foundName = matchTx.userName || matchTx.name;
            }
          }
        } catch(e) {}
      }
      if (isInvalidEmail(foundEmail)) {
        try {
          const storedUser = localStorage.getItem("mmo_user");
          const curU = storedUser ? JSON.parse(storedUser) : (typeof currentUser !== "undefined" ? currentUser : null);
          if (curU && !isInvalidEmail(curU.email)) {
            const curEm = curU.email.toLowerCase().trim();
            if (curEm !== "manhdongvtc@gmail.com" && curEm !== "manhdongdz@gmail.com") {
              foundEmail = curU.email.trim();
              foundName = curU.name || curU.username || foundName;
            }
          }
        } catch(e) {}
      }
      if (isInvalidEmail(foundEmail)) {
        try {
          const registered = typeof getRegisteredUsers === "function" ? getRegisteredUsers() : [];
          const customers = registered.filter(u => {
            const em = (u.email || "").toLowerCase().trim();
            return em && em.includes("@") && em !== "manhdongvtc@gmail.com" && em !== "manhdongdz@gmail.com" && !em.includes("khachhang@gmail.com") && !em.includes("test@gmail.com");
          });
          if (customers.length > 0) {
            const activeCust = customers.find(c => (Number(c.balance) || 0) > 0) || customers[0];
            foundEmail = activeCust.email;
            foundName = activeCust.name || foundEmail.split("@")[0];
          }
        } catch(e) {}
      }
      if (!isInvalidEmail(foundEmail)) {
        order.email = foundEmail;
        order.userEmail = foundEmail;
        if (!foundName || foundName === "Khách Hàng" || foundName === "--") {
          foundName = foundEmail.split("@")[0];
        }
        order.userName = foundName;
        order.name = foundName;
      }
      return order;
    }
    window.autoEnrichOrderCustomerAndTime = autoEnrichOrderCustomerAndTime;
    function resolveOrderDetail(orderId) {
      if (!orderId) return null;
      const cleanId = String(orderId).replace("#", "").trim();
      let orders = typeof getAllOrders === "function" ? getAllOrders() : [];
      let order = orders.find(o => (o.orderId === cleanId || o.id === cleanId));
      let uOrders = typeof getUserOrders === "function" ? getUserOrders() : [];
      let uo = uOrders.find(o => (o.orderId === cleanId || o.id === cleanId));
      const isGeneric = (o) => (!o || !o.productName || o.productName.startsWith("Sản Phẩm Đơn Hàng") || o.productId === "SP_MMO" || o.productName === "Sản phẩm MMO");
      if (uo) {
        if (isGeneric(order) && !isGeneric(uo)) {
          order = Object.assign({}, order || {}, uo);
        }
        if (order) {
          if ((!order.email || order.email === "--") && (uo.email || uo.userEmail)) {
            order.email = uo.email || uo.userEmail;
            order.userEmail = order.email;
          }
          if ((!order.date || order.date === "--") && (uo.date || uo.createdAt)) {
            order.date = uo.date || uo.createdAt;
          }
          if ((!order.userName || order.userName === "Khách Hàng") && (uo.userName || uo.name)) {
            order.userName = uo.userName || uo.name;
          }
        }
      }
      if (isGeneric(order)) {
        const msgs = typeof getAllChatMessages === "function" ? getAllChatMessages() : [];
        for (let i = msgs.length - 1; i >= 0; i--) {
          const m = msgs[i];
          if (!m) continue;
          if (m.orderData && (m.orderData.orderId === cleanId || m.orderData.id === cleanId)) {
            order = Object.assign({}, order || {}, {
              orderId: cleanId,
              id: cleanId,
              productId: m.orderData.productId || (order ? order.productId : ""),
              productName: m.orderData.productName || (order ? order.productName : ""),
              variant: m.orderData.variant || (order ? order.variant : ""),
              quantity: m.orderData.quantity || (order ? order.quantity : 1),
              totalPrice: m.orderData.totalPrice || (order ? order.totalPrice : 0),
              total: m.orderData.totalPrice || (order ? order.total : 0),
              credentials: m.orderData.credentials || (order ? order.credentials : ""),
              email: m.orderData.email || m.orderData.userEmail || m.senderEmail || m.userEmail || (order ? order.email : ""),
              userEmail: m.orderData.userEmail || m.orderData.email || m.senderEmail || (order ? order.userEmail : ""),
              userName: m.orderData.userName || m.orderData.name || (order ? order.userName : ""),
              date: m.orderData.date || m.orderData.createdAt || m.time || m.date || (order ? order.date : "")
            });
            break;
          }
          if (m.text && m.text.includes(cleanId)) {
            const prodMatch = m.text.match(/(?:Sản phẩm|SP):\s*([^|\n\r\-]+)/i);
            const varMatch = m.text.match(/(?:Phân loại|Biến thể):\s*([^|\n\r\-]+)/i) || m.text.match(/🏷️\s*Phân loại:\s*([^\n\r]+)/i);
            const qtyMatch = m.text.match(/(?:Số lượng|SL):\s*(\d+)/i);
            const priceMatch = m.text.match(/(?:Tổng tiền|Tổng|Đã thanh toán|Giá):\s*([\d\.,]+)/i);
            if (prodMatch || varMatch) {
              order = Object.assign({}, order || {}, {
                orderId: cleanId,
                id: cleanId,
                productName: prodMatch ? prodMatch[1].trim() : (order ? order.productName : ""),
                variant: varMatch ? (varMatch[1] || varMatch[0]).trim() : (order ? order.variant : ""),
                quantity: qtyMatch ? parseInt(qtyMatch[1], 10) : (order ? order.quantity : 1),
                totalPrice: priceMatch ? parseInt(priceMatch[1].replace(/[^\d]/g, ""), 10) : (order ? order.totalPrice : 0),
                total: priceMatch ? parseInt(priceMatch[1].replace(/[^\d]/g, ""), 10) : (order ? order.total : 0),
                email: m.senderEmail || m.userEmail || (order ? order.email : ""),
                userEmail: m.senderEmail || m.userEmail || (order ? order.userEmail : ""),
                date: m.time || m.date || (order ? order.date : "")
              });
              break;
            }
          }
        }
      }
      if (isGeneric(order)) {
        try {
          const raw = localStorage.getItem("mmo_transactions") || localStorage.getItem("mmo_wallet_transactions") || "[]";
          const txs = JSON.parse(raw);
          if (Array.isArray(txs)) {
            const match = txs.find(t => String(t.description || "").includes(cleanId) || String(t.memo || "").includes(cleanId));
            if (match && match.description) {
              const m = match.description.match(/Mua SP:\s*([^(]+)(?:\(([^)]+)\))?/i);
              if (m) {
                order = Object.assign({}, order || {}, {
                  orderId: cleanId,
                  id: cleanId,
                  productName: m[1].trim(),
                  variant: m[2] ? m[2].trim() : "Mặc định",
                  totalPrice: Math.abs(Number(match.amount) || 0),
                  total: Math.abs(Number(match.amount) || 0),
                  email: match.userEmail || match.email || (order ? order.email : ""),
                  userEmail: match.userEmail || match.email || (order ? order.userEmail : ""),
                  userName: match.userName || match.name || (order ? order.userName : ""),
                  date: match.date || (order ? order.date : "")
                });
              }
            }
          }
        } catch(e) {}
      }
      if (isGeneric(order)) {
        const targetEmail = (typeof currentAdminChatTargetEmail !== "undefined" && currentAdminChatTargetEmail) ? currentAdminChatTargetEmail.toLowerCase().trim() : "";
        if (targetEmail) {
          const userLatestOrder = orders.find(o => !isGeneric(o) && (o.email || o.userEmail || "").toLowerCase().trim() === targetEmail);
          if (userLatestOrder) {
            order = Object.assign({}, order || {}, {
              productId: userLatestOrder.productId,
              productName: userLatestOrder.productName,
              variant: userLatestOrder.variant,
              quantity: userLatestOrder.quantity || userLatestOrder.qty || 1,
              totalPrice: userLatestOrder.totalPrice || userLatestOrder.total,
              total: userLatestOrder.total || userLatestOrder.totalPrice,
              credentials: userLatestOrder.credentials || userLatestOrder.accounts || (order ? order.credentials : ""),
              email: targetEmail,
              userEmail: targetEmail
            });
          }
        }
      }
      if (!order) {
        order = {
          orderId: cleanId,
          id: cleanId,
          productId: "SP_MMO",
          productName: "Tài khoản MMO",
          variant: "Tiêu chuẩn",
          quantity: 1,
          totalPrice: 0,
          total: 0,
          date: new Date().toLocaleDateString("vi-VN"),
          status: "Khiếu Nại / Bảo Hành",
          credentials: "Chưa có dữ liệu tài khoản cục bộ"
        };
      }
      if ((!order.productId || order.productId === "SP_MMO") && order.productName && typeof MOCK_DATA !== "undefined" && MOCK_DATA.products) {
        const foundProd = MOCK_DATA.products.find(p => p.name.toLowerCase() === order.productName.toLowerCase() || order.productName.toLowerCase().includes(p.name.toLowerCase()) || p.name.toLowerCase().includes(order.productName.toLowerCase()));
        if (foundProd) {
          order.productId = foundProd.id;
          if (!order.productName || order.productName.startsWith("Sản Phẩm Đơn Hàng")) order.productName = foundProd.name;
        }
      }
      order = autoEnrichOrderCustomerAndTime(order, cleanId);
      return order;
    }
